// synth: library theory (phase 0)
// doc: Python's floor division operator (//).
// For integers a and b with b != 0, a // b returns the floor of the mathematical quotient a/b,
// which is the greatest integer less than or equal to a/b.
// When a and b have the same sign, this is equivalent to truncating division.
// When they differ in sign and there is a remainder, the result rounds towards negative infinity.
// Examples: 7 // 2 = 3, -7 // 2 = -4, 7 // -2 = -4.
// Raises ZeroDivisionError if b == 0.
function FloorDiv(a: int, b: int): int
  requires b != 0
{
  if (a >= 0 && b > 0) || (a <= 0 && b < 0) then
    a / b
  else
    if a % b == 0 then a / b else a / b - 1
}

