theory:
// synth: library theory (phase 0)
// doc: Python's floor division operator //. For integers n and d where d != 0,
// n // d returns the largest integer q such that q * d <= n < (q + 1) * d.
// This rounds towards negative infinity. For example: 7 // 2 = 3, (-7) // 2 = -4,
// 7 // (-2) = -4. Raises ZeroDivisionError if d = 0.
function FloorDiv(n: int, d: int): int
  requires d != 0
{
  if (n >= 0 && d > 0) || (n < 0 && d < 0) then
    n / d
  else if n % d == 0 then
    n / d
  else
    n / d - 1
}

