// src: source.py:1 | def right_angle_triangle(a, b, c):
method right_angle_triangle(a: int, b: int, c: int) returns (result: bool)
  // synth: precondition from docstring: "the lengths of the three sides of a triangle"
  requires a > 0
  requires b > 0
  requires c > 0
  requires a + b > c
  requires a + c > b
  requires b + c > a
  // synth: postcondition from assert
  ensures result == (a * a + b * b == c * c || a * a + c * c == b * b || b * b + c * c == a * a)
{
  // synth: local variables
  var hypotenuse: int;
  var side1: int;
  var side2: int;

  // src: source.py:2 | if a > c and b > c:
  if a > c && b > c {
    // src: source.py:3 | hypotenuse = a
    hypotenuse := a;
    // src: source.py:4 | side1 = b
    side1 := b;
    // src: source.py:5 | side2 = c
    side2 := c;
  }
  // src: source.py:6 | elif b > a and c > a:
  else if b > a && c > a {
    // src: source.py:7 | hypotenuse = b
    hypotenuse := b;
    // src: source.py:8 | side1 = a
    side1 := a;
    // src: source.py:9 | side2 = c
    side2 := c;
  }
  // src: source.py:10 | else:
  else {
    // src: source.py:11 | hypotenuse = c
    hypotenuse := c;
    // src: source.py:12 | side1 = a
    side1 := a;
    // src: source.py:13 | side2 = b
    side2 := b;
  }

  // src: source.py:14 | if hypotenuse ** 2 == side1 ** 2 + side2 ** 2:
  if hypotenuse * hypotenuse == side1 * side1 + side2 * side2 {
    // src: source.py:15 | return True
    return true;
  }
  // src: source.py:16 | else:
  else {
    // src: source.py:17 | return False
    return false;
  }
}

