// synth: lemma: if the largest of three values doesn't satisfy the Pythagorean
// theorem, then none of the three combinations do
lemma LargestNotPythagorean(largest: int, other1: int, other2: int, a: int, b: int, c: int)
  requires largest >= other1 && largest >= other2
  requires largest * largest != other1 * other1 + other2 * other2
  requires (largest == a && other1 == b && other2 == c) ||
           (largest == a && other1 == c && other2 == b) ||
           (largest == b && other1 == a && other2 == c) ||
           (largest == b && other1 == c && other2 == a) ||
           (largest == c && other1 == a && other2 == b) ||
           (largest == c && other1 == b && other2 == a)
  ensures a * a + b * b != c * c && a * a + c * c != b * b && b * b + c * c != a * a
{
  // In any valid right triangle, the hypotenuse must be the largest side.
  // Since the largest side squared doesn't equal the sum of the other two squared,
  // there is no right triangle among a, b, c.
}
